package main

import (
	"context"
	"log"
	"net/http"
	"sync"
	"time"
)

type App struct {
	DB       *DB
	Mux      *http.ServeMux
	events   *EventBus
	svcMu    sync.Mutex
	svcCurrentVersion int
}

type ctxKey string

const ctxUserKey ctxKey = "authed_user"

func userFromCtx(ctx context.Context) *AuthedUser {
	v := ctx.Value(ctxUserKey)
	if v == nil {
		return nil
	}
	return v.(*AuthedUser)
}

// withAuth ensures a valid bearer [REDACTED]; does not require a role to be selected.
func (app *App) withAuth(next func(w http.ResponseWriter, r *http.Request, u *AuthedUser)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := extractBearer(r)
		if tok == "" {
			writeErr(w, errUnauthorized())
			return
		}
		u, err := app.authenticate(r.Context(), tok)
		if err != nil {
			writeErr(w, err)
			return
		}
		ctx := context.WithValue(r.Context(), ctxUserKey, u)
		next(w, r.WithContext(ctx), u)
	}
}

// withRole ensures auth + an active role is selected + (if roles given) the active role is one of them.
func (app *App) withRole(allowed []string, next func(w http.ResponseWriter, r *http.Request, u *AuthedUser)) http.HandlerFunc {
	return app.withAuth(func(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
		if u.ActiveRole == "" {
			writeErr(w, errRoleNotSelected())
			return
		}
		if len(allowed) > 0 {
			ok := false
			for _, a := range allowed {
				if a == u.ActiveRole {
					ok = true
					break
				}
			}
			if !ok {
				writeErr(w, errForbidden())
				return
			}
		}
		next(w, r, u)
	})
}

func extractBearer(r *http.Request) string {
	h := r.Header.Get("Authorization")
	const p = "Bearer "
	if len(h) > len(p) && h[:len(p)] == p {
		return h[len(p):]
	}
	return ""
}

func mustAtoi(s string, def int) int {
	n := 0
	neg := false
	if s == "" {
		return def
	}
	for i, c := range s {
		if i == 0 && c == '-' {
			neg = true
			continue
		}
		if c < '0' || c > '9' {
			return def
		}
		n = n*10 + int(c-'0')
	}
	if neg {
		n = -n
	}
	return n
}

func nowUTC() time.Time { return time.Now().UTC() }

func logf(format string, args ...interface{}) {
	log.Printf(format, args...)
