}

func newEventBus() *EventBus {
	return &EventBus{subs: map[chan RealtimeEvent]bool{}}
}

func (b *EventBus) subscribe() chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 64)
	b.mu.Lock()
	b.subs[ch] = true
	b.mu.Unlock()
	return ch
}

func (b *EventBus) unsubscribe(ch chan RealtimeEvent) {
	b.mu.Lock()
	delete(b.subs, ch)
	b.mu.Unlock()
	close(ch)
}

func (b *EventBus) publish(ev RealtimeEvent) {
	b.mu.Lock()
	defer b.mu.Unlock()
