package main

import (
	"container/heap"
	"context"
	"time"

	"github.com/jackc/pgx/v5"
)

type locNode struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	IsCollection    bool
	IsTransfer      bool
	IsHub           bool
	IsLab           bool
	CapacityUnits, ReservedUnits             int
	CooledCapacityUnits, CooledReservedUnits int
}

type edge struct {
	ID             string
	From, To       string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
	CapacityUnits, ReservedUnits             int
	CooledCapacityUnits, CooledReservedUnits int
}

type networkGraph struct {
	Nodes map[string]*locNode
	Edges []edge
	Adj   map[string][]int // location id -> edge indices
	LabAccepts map[string]map[string]bool // labID -> sampleTypeID -> accepts
}

func (app *App) loadNetworkGraph(ctx context.Context) (*networkGraph, error) {
	g := &networkGraph{Nodes: map[string]*locNode{}, Adj: map[string][]int{}, LabAccepts: map[string]map[string]bool{}}

	rows, err := app.DB.Pool.Query(ctx, `
		SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
		       is_collection_point, is_transfer_point, is_hub, is_laboratory,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		n := &locNode{}
		if err := rows.Scan(&n.ID, &n.Name, &n.Lat, &n.Lng, &n.CoverageKm, &n.HandlingMinutes, &n.Active,
			&n.IsCollection, &n.IsTransfer, &n.IsHub, &n.IsLab,
			&n.CapacityUnits, &n.ReservedUnits, &n.CooledCapacityUnits, &n.CooledReservedUnits); err != nil {
			rows.Close()
			return nil, err
		}
		g.Nodes[n.ID] = n
	}
	rows.Close()

	erows, err := app.DB.Pool.Query(ctx, `
		SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections`)
	if err != nil {
		return nil, err
	}
	for erows.Next() {
		e := edge{}
		if err := erows.Scan(&e.ID, &e.From, &e.To, &e.TravelMinutes, &e.CostUnits, &e.Cooled, &e.Active,
			&e.CapacityUnits, &e.ReservedUnits, &e.CooledCapacityUnits, &e.CooledReservedUnits); err != nil {
			erows.Close()
			return nil, err
		}
		idx := len(g.Edges)
		g.Edges = append(g.Edges, e)
		g.Adj[e.From] = append(g.Adj[e.From], idx)
		// connections are usable in both directions for transport purposes
		g.Adj[e.To] = append(g.Adj[e.To], idx)
	}
	erows.Close()

	lrows, err := app.DB.Pool.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
	if err != nil {
		return nil, err
	}
	for lrows.Next() {
		var lab, st string
		var accepts bool
		if err := lrows.Scan(&lab, &st, &accepts); err != nil {
			continue
		}
		if g.LabAccepts[lab] == nil {
			g.LabAccepts[lab] = map[string]bool{}
		}
		g.LabAccepts[lab][st] = accepts
	}
	lrows.Close()

	return g, nil
}

// --- Dijkstra ---

type pqItem struct {
	loc      string
	dist     int
	pathEdge int // edge index used to arrive here (-1 for source)
	prevLoc  string
}

type priorityQueue []*pqItem

func (pq priorityQueue) Len() int            { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool  { return pq[i].dist < pq[j].dist }
func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(*pqItem)) }
func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	it := old[n-1]
	*pq = old[:n-1]
	return it
}

type routeResult struct {
	PathLocations []string // ordered location ids, including entry and destination lab
	PathEdges     []string // connection ids used, len = len(PathLocations)-1
	TotalMinutes  int
	LabID         string
}

// findRoute runs Dijkstra from entryLocationID to the nearest active, accepting laboratory,
// honoring cooled-route requirements when requireCooled is true.
func findRoute(g *networkGraph, entryLocationID, sampleTypeID string, requireCooled bool) *routeResult {
	entry, ok := g.Nodes[entryLocationID]
	if !ok || !entry.Active {
		return nil
	}
	dist := map[string]int{entryLocationID: 0}
	prevEdge := map[string]int{}
	prevLoc := map[string]string{}
	visited := map[string]bool{}

	pq := &priorityQueue{{loc: entryLocationID, dist: 0, pathEdge: -1}}
	heap.Init(pq)

	// If entry itself is an accepting active lab, trivially return it.
	if entry.IsLab && g.LabAccepts[entryLocationID][sampleTypeID] {
		return &routeResult{PathLocations: []string{entryLocationID}, PathEdges: []string{}, TotalMinutes: 0, LabID: entryLocationID}
	}

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*pqItem)
		if visited[cur.loc] {
			continue
		}
		visited[cur.loc] = true

		node := g.Nodes[cur.loc]
		if node != nil && node.IsLab && g.LabAccepts[cur.loc][sampleTypeID] && cur.loc != entryLocationID {
			// reconstruct path
			pathLocs := []string{}
			pathEdges := []string{}
			loc := cur.loc
			for {
				pathLocs = append([]string{loc}, pathLocs...)
				pe, ok := prevEdge[loc]
				if !ok {
					break
				}
				pathEdges = append([]string{g.Edges[pe].ID}, pathEdges...)
				loc = prevLoc[loc]
				if loc == entryLocationID {
					pathLocs = append([]string{loc}, pathLocs...)
					break
				}
			}
			return &routeResult{PathLocations: pathLocs, PathEdges: pathEdges, TotalMinutes: cur.dist, LabID: cur.loc}
		}

		for _, ei := range g.Adj[cur.loc] {
			e := g.Edges[ei]
			if !e.Active {
				continue
			}
			if requireCooled && !e.Cooled {
				continue
			}
			var next string
			if e.From == cur.loc {
				next = e.To
			} else if e.To == cur.loc {
				next = e.From
			} else {
				continue
			}
			nn := g.Nodes[next]
			if nn == nil || !nn.Active {
				continue
			}
			nd := cur.dist + e.TravelMinutes
			if existing, ok := dist[next]; !ok || nd < existing {
				dist[next] = nd
				prevEdge[next] = ei
				prevLoc[next] = cur.loc
				heap.Push(pq, &pqItem{loc: next, dist: nd, pathEdge: ei, prevLoc: cur.loc})
			}
		}
	}
	return nil
}

// findEntryLocation resolves the collection entry point for a request origin.
func findEntryLocation(g *networkGraph, originType string, lat, lng float64, originNodeID string) *locNode {
	if originType == "node" && originNodeID != "" {
		n := g.Nodes[originNodeID]
		if n == nil || !n.Active {
			return nil
		}
		return n
	}
	var best *locNode
	bestDist := 1e18
	for _, n := range g.Nodes {
		if !n.Active || !n.IsCollection {
			continue
		}
		d := haversineKm(lat, lng, n.Lat, n.Lng)
		cov := n.CoverageKm
		if cov <= 0 || cov > 5 {
			cov = 5
		}
		if d <= cov && d < bestDist {
			bestDist = d
			best = n
		}
	}
	return best
}

// capacityCheck verifies that all nodes and edges in the given path have at least
// one available unit in the required pool (regular or cooled).
func capacityCheck(g *networkGraph, path []string, edges []string, cooled bool) bool {
	for _, locID := range path {
		n := g.Nodes[locID]
		if n == nil {
			return false
		}
		if cooled {
			if n.CooledCapacityUnits-n.CooledReservedUnits < 1 {
				return false
			}
		} else {
			if n.CapacityUnits-n.ReservedUnits < 1 {
				return false
			}
		}
	}
	for _, eid := range edges {
		for _, e := range g.Edges {
			if e.ID == eid {
				if cooled {
					if e.CooledCapacityUnits-e.CooledReservedUnits < 1 {
						return false
					}
				} else {
					if e.CapacityUnits-e.ReservedUnits < 1 {
						return false
					}
				}
			}
		}
	}
	return true
}

type planOutcome struct {
	Serviceable   bool
	Reason        string
	LabID         string
	EstimatedAt   time.Time
	PathLocations []string
	PathEdges     []string
	TotalMinutes  int
}

// planRoute computes a full serviceability+routing outcome without persisting anything.
func (app *App) planRoute(ctx context.Context, originType string, lat, lng float64, originNodeID string,
	sampleTypeID string, requireCooled bool, startAt time.Time, deadline time.Time) (*planOutcome, *networkGraph, error) {

	g, err := app.loadNetworkGraph(ctx)
	if err != nil {
		return nil, nil, err
	}

	entry := findEntryLocation(g, originType, lat, lng, originNodeID)
	if entry == nil {
		return &planOutcome{Serviceable: false, Reason: "outside_service_coverage"}, g, nil
	}

	route := findRoute(g, entry.ID, sampleTypeID, requireCooled)
	if route == nil {
		return &planOutcome{Serviceable: false, Reason: "no_accepting_laboratory"}, g, nil
	}

	if !capacityCheck(g, route.PathLocations, route.PathEdges, requireCooled) {
		return &planOutcome{Serviceable: false, Reason: "insufficient_capacity"}, g, nil
	}

	// Estimate arrival time by walking the path, accumulating handling + travel minutes.
	t := startAt
	t = t.Add(time.Duration(g.Nodes[route.PathLocations[0]].HandlingMinutes) * time.Minute)
	for i := 1; i < len(route.PathLocations); i++ {
		edgeID := route.PathEdges[i-1]
		var mins int
		for _, e := range g.Edges {
			if e.ID == edgeID {
				mins = e.TravelMinutes
				break
			}
		}
		t = t.Add(time.Duration(mins) * time.Minute)
		t = t.Add(time.Duration(g.Nodes[route.PathLocations[i]].HandlingMinutes) * time.Minute)
	}

	if t.After(deadline) {
		return &planOutcome{Serviceable: false, Reason: "deadline_unreachable", LabID: route.LabID, EstimatedAt: t,
			PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes}, g, nil
	}

	return &planOutcome{
		Serviceable: true, Reason: "serviceable", LabID: route.LabID, EstimatedAt: t,
		PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes,
	}, g, nil
}

// reserveCapacityForJourney reserves 1 unit (regular or cooled) at every node & edge in
// the path and records rows in capacity_reservations for later release.
func reserveCapacityForJourney(ctx context.Context, tx pgx.Tx, journeyID, sampleID string, path []string, edges []string, cooled bool) error {
	for _, locID := range path {
		col := "reserved_units"
		capCol := "capacity_units"
		if cooled {
			col = "cooled_reserved_units"
			capCol = "cooled_capacity_units"
		}
		res, err := tx.Exec(ctx, `UPDATE locations SET `+col+` = `+col+` + 1, updated_at=now()
			WHERE id = $1 AND `+col+` + 1 <= `+capCol, locID)
		if err != nil {
			return err
		}
		if res.RowsAffected() == 0 {
			return newErr(409, "capacity_exhausted", "capacity exhausted at location "+locID)
		}
		_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'location',$3,$4,1)`,
			sampleID, journeyID, locID, cooled)
		if err != nil {
			return err
		}
	}
	for _, eid := range edges {
		col := "reserved_units"
		capCol := "capacity_units"
		if cooled {
			col = "cooled_reserved_units"
			capCol = "cooled_capacity_units"
		}
		res, err := tx.Exec(ctx, `UPDATE connections SET `+col+` = `+col+` + 1, updated_at=now()
			WHERE id = $1 AND `+col+` + 1 <= `+capCol, eid)
		if err != nil {
			return err
		}
		if res.RowsAffected() == 0 {
			return newErr(409, "cooled_capacity_exhausted", "capacity exhausted on connection "+eid)
		}
		_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'connection',$3,$4,1)`,
			sampleID, journeyID, eid, cooled)
		if err != nil {
			return err
		}
	}
	return nil
}

// releaseJourneyCapacity releases all capacity reservations tied to a journey.
func releaseJourneyCapacity(ctx context.Context, tx pgx.Tx, journeyID string) error {
	rows, err := tx.Query(ctx, `SELECT id, pool_type, pool_id, cooled, units FROM capacity_reservations WHERE journey_id = $1 AND released = false`, journeyID)
	if err != nil {
		return err
	}
	type r struct {
		id       string
		poolType string
		poolID   string
		cooled   bool
		units    int
	}
	var list []r
	for rows.Next() {
		var it r
		if err := rows.Scan(&it.id, &it.poolType, &it.poolID, &it.cooled, &it.units); err != nil {
			rows.Close()
			return err
		}
		list = append(list, it)
	}
	rows.Close()

	for _, it := range list {
		col := "reserved_units"
		if it.cooled {
			col = "cooled_reserved_units"
		}
		table := "locations"
		if it.poolType == "connection" {
			table = "connections"
		}
		_, err := tx.Exec(ctx, `UPDATE `+table+` SET `+col+` = GREATEST(`+col+` - $1, 0), updated_at=now() WHERE id = $2`, it.units, it.poolID)
		if err != nil {
			return err
		}
		_, err = tx.Exec(ctx, `UPDATE capacity_reservations SET released = true, released_at = now() WHERE id = $1`, it.id)
		if err != nil {
			return err
		}
	}
	return nil
}

