// activateNextAssignment finds the earliest not-yet-offered assignment on the journey
// whose predecessor assignment (by sequence) is completed, and offers it to the best
// eligible available worker. If none are eligible/available, it leaves the assignment
// pending (unassigned) for the sweeper to retry, and if it has been pending "long enough"
// with zero eligible workers ever available it will be flagged as an exception by the
// sweeper instead.
func (app *App) activateNextAssignment(ctx context.Context, tx pgx.Tx, journeyID string) error {
	rows, err := tx.Query(ctx, `
		SELECT id, journey_id, kind, sequence, sample_id, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''),
		       COALESCE(node_id::text,''), COALESCE(laboratory_id::text,''), status, declined_worker_ids
