action.command:
cd /workspace && python3 << 'EOF'
import json
d = json.load(open('contracts/openapi.contract.json'))

def summarize_schema(schema, depth=0):
    if schema is None:
        return None
    if '$ref' in schema:
        return {'$ref': schema['$ref']}
    t = schema.get('type')
    out = {}
    if t == 'object':
        props = schema.get('properties', {})
        out['type'] = 'object'
        out['required'] = schema.get('required', [])
        out['properties'] = {k: summarize_schema(v, depth+1) if depth < 2 else {'type': v.get('type'), '$ref': v.get('$ref')} for k, v in props.items()}
    elif t == 'array':
        out['type'] = 'array'
        out['items'] = summarize_schema(schema.get('items'), depth+1) if depth < 2 else None
    else:
        out = {k: v for k, v in schema.items() if k in ('type','enum','format','minimum','maximum')}
    return out

result = {}
for path, methods in d['paths'].items():
    for method, op in methods.items():
        opid = op.get('operationId')
        entry = {'path': path, 'method': method, 'operationId': opid}
        rb = op.get('requestBody')
        if rb:
            schema = rb['content']['application/json']['schema']
            entry['requestBody'] = summarize_schema(schema)
        params = op.get('parameters', [])
        if params:
            entry['parameters'] = [{'name': p.get('name'), 'in': p.get('in'), 'required': p.get('required'), 'schema': p.get('schema')} for p in params]
        responses = {}
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content', {}).get('application/json', {})
            schema = content.get('schema')
            responses[code] = summarize_schema(schema)
        entry['responses'] = responses
        result[f"{method.upper()} {path}"] = entry

with open('/tmp/summary2.json', 'w') as f:
    json.dump(result, f, indent=2)
print(len(result))
EOF
wc -l /tmp/summary2.json

