import json
d = json.load(open('/workspace/contracts/openapi.contract.json'))

def req_props(schema):
    if not schema:
        return None
    if '$ref' in schema:
        return schema['$ref'].split('/')[-1]
    t = schema.get('type')
    if t == 'object':
        req = schema.get('required', [])
        props = schema.get('properties', {})
        out = {}
        for k, v in props.items():
            if '$ref' in v:
                out[k] = v['$ref'].split('/')[-1] + ('*' if k in req else '')
                continue
            vt = v.get('type', '?')
            extra = ''
            if 'enum' in v:
                extra = '[' + ','.join(map(str,v['enum'])) + ']'
            if vt == 'array':
                items = v.get('items', {})
                if '$ref' in items:
                    vt = 'array<' + items['$ref'].split('/')[-1] + '>'
                else:
                    vt = 'array<' + items.get('type','?') + '>'
            out[k] = f"{vt}{extra}" + ('*' if k in req else '')
        return out
    if t == 'array':
        items = schema.get('items', {})
        if '$ref' in items:
            return 'array<' + items['$ref'].split('/')[-1] + '>'
        return 'array<' + items.get('type','?') + '>'
    return t

lines = []
for path, methods in d['paths'].items():
    for method, op in methods.items():
        opid = op.get('operationId')
        lines.append(f"### {method.upper()} {path}  [{opid}]")
        params = op.get('parameters', [])
        if params:
            for p in params:
                lines.append(f"  param: {p.get('name')} in={p.get('in')} required={p.get('required')} schema={p.get('schema')}")
        rb = op.get('requestBody')
        if rb:
            schema = rb['content']['application/json']['schema']
            lines.append(f"  body: {json.dumps(req_props(schema))}")
        for code, resp in sorted(op.get('responses', {}).items()):
            content = resp.get('content', {}).get('application/json', {})
            schema = content.get('schema')
            summary = req_props(schema)
            # for error responses just show code enum
            if isinstance(summary, dict) and 'code' in summary:
                lines.append(f"  {code}: code={summary.get('code')}")
            else:
                lines.append(f"  {code}: {json.dumps(summary)}")
        lines.append("")

with open('/tmp/compact.txt', 'w') as f:
    f.write('\n'.join(lines))
print(len(lines))

