type apiError struct {
        Status int
        Code   string
        Msg    string
}

func (e *apiError) Error() string { return e.Msg }

func newErr(status int, code, msg string) *apiError {
        return &apiError{Status: status, Code: code, Msg: msg}
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
        w.Header().Set("Content-Type", "application/json")
        w.WriteHeader(status)
        _ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
        writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, err error) {
        if ae, ok := err.(*apiError); ok {
                writeJSON(w, ae.Status, map[string]interface{}{"error": ae.Msg, "code": ae.Code})
                return
        }
        writeJSON(w, 500, map[string]interface{}{"error": "internal error", "code": "internal_error"})
}

func errInvalidJSON(msg string) *apiError    { return newErr(400, "invalid_json", msg) }
func errUnauthorized() *apiError             { return newErr(401, "unauthorized", "unauthorized") }
func errForbidden() *apiError                { return newErr(403, "forbidden", "forbidden") }
func errNotFound() *apiError                 { return newErr(404, "not_found", "not found") }
func errRoleNotSelected() *apiError          { return newErr(409, "role_not_selected", "no active role selected") }
func errIdempotencyRequired() *apiError      { return newErr(400, "idempotency_required", "idempotencyKey is required") }
func errIdempotencyConflict() *apiError      { return newErr(409, "idempotency_conflict", "idempotency key already used with a different request") }
func errConcurrentConflict() *apiError       { return newErr(409, "concurrent_conflict", "concurrent modification detected") }
func errInternal(msg string) *apiError       { return newErr(500, "internal_error", msg) }

func decodeJSONBody(r *http.Request, v interface{}) error {
        dec := json.NewDecoder(r.Body)
        dec.DisallowUnknownFields()
        if err := dec.Decode(v); err != nil {
                return errInvalidJSON(err.Error())
        }
        return nil
}

