import (
        "context"
        "crypto/rand"
        "crypto/sha256"
        "encoding/hex"
        "fmt"
        "os"
        "time"

        "github.com/golang-jwt/jwt/v5"
        "github.com/google/uuid"
)

var jwtSecret []byte

func initJWTSecret() {
        s := os.Getenv("JWT_SECRET")
        if s == "" {
                s = "lab-sample-dev-secret-change-me"
        }
        jwtSecret = []byte(s)
}

func hashPassword(password string) string {
        salt := make([]byte, 16)
        _, _ = rand.Read(salt)
        saltHex := hex.EncodeToString(salt)
        h := sha256.Sum256([]byte(saltHex + ":" + password))
        return saltHex + ":" + hex.EncodeToString(h[:])
}

func verifyPassword(password, stored string) bool {
        var saltHex string
        for i := 0; i < len(stored); i++ {
                if stored[i] == ':' {
                        saltHex = stored[:i]
                        break
                }
        }
        if saltHex == "" {
                return false
        }
        h := sha256.Sum256([]byte(saltHex + ":" + password))
        expected := saltHex + ":" + hex.EncodeToString(h[:])
        return expected == stored
}

type sessionClaims struct {
        SessionID string `json:"sid"`
        UserID    string `json:"uid"`
        jwt.RegisteredClaims
}

func issueToken(sessionID, userID string) (string, error) {
        claims := sessionClaims{
                SessionID: sessionID,
                UserID:    userID,
                RegisteredClaims: jwt.RegisteredClaims{
                        IssuedAt:  jwt.NewNumericDate(time.Now()),
                        ExpiresAt: jwt.NewNumericDate(time.Now().Add(24 * time.Hour)),
                },
        }
        tok := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
        return tok.SignedString(jwtSecret)
}

func parseToken(tokenStr string) (*sessionClaims, error) {
        claims := &sessionClaims{}
        _, err := jwt.ParseWithClaims(tokenStr, claims, func(t *jwt.Token) (interface{}, error) {
                return jwtSecret, nil
        })
        if err != nil {
                return nil, err
        }
        return claims, nil
}

type AuthedUser struct {
        UserID     string
        Username   string
        FullName   string
        Roles      []string
        Qualifications []string
        Active     bool
        AssignedLocationID string
        SessionID  string
        ActiveRole string
}

func (app *App) authenticate(ctx context.Context, tokenStr string) (*AuthedUser, error) {
        claims, err := parseToken(tokenStr)
        if err != nil {
                return nil, errUnauthorized()
        }
        row := app.DB.Pool.QueryRow(ctx, `
                SELECT s.id, s.active_role, s.revoked, u.id, u.username, u.full_name, u.roles, u.qualifications, u.active, COALESCE(u.assigned_location_id::text, '')
                FROM sessions s JOIN users u ON u.id = s.user_id
                WHERE s.id = $1`, claims.SessionID)
        var sessID, activeRole, uid, username, fullName, assignedLoc string
        var revoked, active bool
        var roles, quals []string
        if err := row.Scan(&sessID, &activeRole, &revoked, &uid, &username, &fullName, &roles, &quals, &active, &assignedLoc); err != nil {
                return nil, errUnauthorized()
        }
        if revoked || !active {
                return nil, errUnauthorized()
        }
        return &AuthedUser{
                UserID: uid, Username: username, FullName: fullName, Roles: roles, Qualifications: quals,
                Active: active, AssignedLocationID: assignedLoc, SessionID: sessID, ActiveRole: activeRole,
        }, nil
}

func newSession(ctx context.Context, app *App, userID string) (string, string, error) {
        id := uuid.New().String()
        _, err := app.DB.Pool.Exec(ctx, `INSERT INTO sessions (id, user_id, active_role) VALUES ($1,$2,NULL)`, id, userID)
        if err != nil {
                return "", "", err
        }
        tok, err := issueToken(id, userID)
        if err != nil {
                return "", "", err
        }
        return tok, id, nil
}

func hasRole(u *AuthedUser, role string) bool {
        for _, r := range u.Roles {
                if r == role {
                        return true
                }
        }
        return false
}

func genRandomHex(n int) string {
        b := make([]byte, n)
        _, _ = rand.Read(b)
        return hex.EncodeToString(b)
}

func fmtErr(context string, err error) error {
        return fmt.Errorf("%s: %w", context, err)
}

