                "auditId":    id,
                "audit_id":   id,
                "actorId":    actorID,
                "actor_id":   actorID,
                "role":       role,
                "actorRole":  role,
                "action":     action,
                "entityType": entityType,
                "entity_type": entityType,
                "entityId":   entityID,
                "entity_id":  entityID,
                "success":    success,
                "occurredAt": occurredAt,
                "occurred_at": occurredAt,
                "details":    details,
                "searchText": strings.Join(searchParts, " "),
        }
        _, err := app.DB.Audit.InsertOne(ctx, doc)
        if err != nil {
                logf("mongo audit insert failed: %v", err)
        }
