}

package main

import (
        "context"
        "time"

        "github.com/jackc/pgx/v5"
)

const offerTTL = 2 * time.Minute

// eligibleWorkersForAssignment returns candidate worker ids/roles for the given
// assignment kind, respecting qualification (for collection), and node/lab assignment.
func (app *App) eligibleWorkersForAssignment(ctx context.Context, tx pgx.Tx, kind, sampleTypeID, locationID string, declinedIDs []string) ([]string, error) {
        var role string
        switch kind {
        case "collection":
                role = RoleCollectionProfessional
        case "transport":
                role = RoleDeliveryPartner
        case "node":
                role = RoleNodeHandler
        case "laboratory":
                role = RoleLaboratoryTeam
        default:
                return nil, nil
        }

        query := `
                SELECT u.id FROM users u
                LEFT JOIN worker_stats ws ON ws.worker_id = u.id
                WHERE u.active = true AND $1 = ANY(u.roles)
        `
        args := []interface{}{role}
        argN := 2

        if kind == "node" || kind == "laboratory" {
                query += ` AND u.assigned_location_id = $` + itoa(argN)
                args = append(args, locationID)
                argN++
        }

        if kind == "collection" && sampleTypeID != "" {
                query += ` AND EXISTS (
                        SELECT 1 FROM sample_types st WHERE st.id = $` + itoa(argN) + `
                        AND (st.required_qualification IS NULL OR st.required_qualification = ANY(u.qualifications))
                )`
                args = append(args, sampleTypeID)
                argN++
        }

        query += ` AND COALESCE(ws.available, true) = true`
        query += ` ORDER BY COALESCE(ws.assignment_count,0) ASC,
                CASE WHEN ws.last_decline_at IS NOT NULL AND ws.last_decline_at > now() - interval '10 minutes' THEN 1 ELSE 0 END ASC,
                u.created_at ASC`

        rows, err := tx.Query(ctx, query, args...)
        if err != nil {
                return nil, err
        }
        defer rows.Close()
        var out []string
        for rows.Next() {
                var id string
                if err := rows.Scan(&id); err != nil {
                        continue
                }
                skip := false
                for _, d := range declinedIDs {
                        if d == id {
                                skip = true
                                break
                        }
                }
                if !skip {
                        out = append(out, id)
                }
        }
        return out, nil
}

func itoa(n int) string {
        if n == 0 {
                return "0"
        }
        neg := n < 0
        if neg {
                n = -n
        }
        var buf [20]byte
        i := len(buf)
        for n > 0 {
                i--
                buf[i] = byte('0' + n%10)
                n /= 10
        }
        if neg {
                i--
                buf[i] = '-'
        }
        return string(buf[i:])
}

type assignmentRow struct {
        ID           string
        JourneyID    string
        Kind         string
        Sequence     int
        SampleID     string
        FromLocID    string
        ToLocID      string
        NodeID       string
        LaboratoryID string
        Status       string
        DeclinedIDs  []string
}

// activateNextAssignment finds the earliest not-yet-offered assignment on the journey
// whose predecessor assignment (by sequence) is completed, and offers it to the best
// eligible available worker. If none are eligible/available, it leaves the assignment
// pending (unassigned) for the sweeper to retry, and if it has been pending "long enough"
// with zero eligible workers ever available it will be flagged as an exception by the
// sweeper instead.
func (app *App) activateNextAssignment(ctx context.Context, tx pgx.Tx, journeyID string) error {
        rows, err := tx.Query(ctx, `
                SELECT id, journey_id, kind, sequence, sample_id, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''),
                       COALESCE(node_id::text,''), COALESCE(laboratory_id::text,''), status, declined_worker_ids
                FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
        if err != nil {
                return err
        }
        var list []assignmentRow
        for rows.Next() {
                var a assignmentRow
                if err := rows.Scan(&a.ID, &a.JourneyID, &a.Kind, &a.Sequence, &a.SampleID, &a.FromLocID, &a.ToLocID, &a.NodeID, &a.LaboratoryID, &a.Status, &a.DeclinedIDs); err != nil {
                        rows.Close()
                        return err
                }
                list = append(list, a)
        }
        rows.Close()

        for i, a := range list {
                if a.Status != "pending" {
                        continue
                }
                if i > 0 && list[i-1].Status != "completed" {
                        break // predecessor not done yet; cannot activate this one
                }
                return app.tryOfferAssignment(ctx, tx, &a)
        }
        return nil
}

func (app *App) tryOfferAssignment(ctx context.Context, tx pgx.Tx, a *assignmentRow) error {
        locationID := a.NodeID
        if a.Kind == "laboratory" {
                locationID = a.LaboratoryID
        }
        var sampleTypeID string
        tx.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE id=$1`, a.SampleID).Scan(&sampleTypeID)

        candidates, err := app.eligibleWorkersForAssignment(ctx, tx, a.Kind, sampleTypeID, locationID, a.DeclinedIDs)
        if err != nil {
                return err
        }
        if len(candidates) == 0 {
                // No eligible worker right now; leave pending, sweeper will retry / flag exception.
                return nil
        }
        worker := candidates[0]
        expires := nowUTC().Add(offerTTL)
        _, err = tx.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$1, offer_expires_at=$2, updated_at=now() WHERE id=$3`,
                worker, expires, a.ID)
        if err != nil {
                return err
        }
        return nil
}

