package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"time"
)

func main() {
	initJWTSecret()

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	pool, err := connectPostgres(ctx)
	if err != nil {
		log.Fatalf("postgres connect: %v", err)
	}
	if err := applyMigrations(ctx, pool); err != nil {
		log.Fatalf("migrate: %v", err)
	}
	mongoClient, err := connectMongo(ctx)
	if err != nil {
		log.Fatalf("mongo connect: %v", err)
	}
	auditColl, err := ensureMongoIndexes(ctx, mongoClient)
	if err != nil {
		log.Fatalf("mongo indexes: %v", err)
	}
	cancel()

	db := &DB{Pool: pool, Mongo: mongoClient, Audit: auditColl}
	app := &App{DB: db, events: newEventBus()}

	if err := seedDefaults(context.Background(), app); err != nil {
		log.Fatalf("seed defaults: %v", err)
	}

	mux := http.NewServeMux()
	app.Mux = mux
	registerRoutes(app, mux)

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}

	go app.startBackgroundSweeper()

	srv := &http.Server{
		Addr:    addr,
		Handler: withCORS(mux),
	}
	log.Printf("listening on %s", addr)
	if err := srv.ListenAndServe(); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

func withCORS(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization,Content-Type,Sec-WebSocket-Protocol")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

