package main

import (
        "context"
        _ "embed"
        "fmt"
        "log"
        "os"
        "time"

        "github.com/jackc/pgx/v5/pgxpool"
        "go.mongodb.org/mongo-driver/v2/mongo"
        "go.mongodb.org/mongo-driver/v2/mongo/options"
)

//go:embed schema.sql
var schemaSQL string

type DB struct {
        Pool  *pgxpool.Pool
        Mongo *mongo.Client
        Audit *mongo.Collection
}

func connectPostgres(ctx context.Context) (*pgxpool.Pool, error) {
        url := os.Getenv("DATABASE_URL")
        if url == "" {
                url = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
        }
        cfg, err := pgxpool.ParseConfig(url)
        if err != nil {
                return nil, err
        }
        cfg.MaxConns = 20
        pool, err := pgxpool.NewWithConfig(ctx, cfg)
        if err != nil {
                return nil, err
        }
        return pool, nil
}

func connectMongo(ctx context.Context) (*mongo.Client, error) {
        uri := os.Getenv("MONGODB_URI")
        if uri == "" {
                uri = "mongodb://127.0.0.1:27017/arena"
        }
        client, err := mongo.Connect(options.Client().ApplyURI(uri))
        if err != nil {
                return nil, err
        }
        ctx2, cancel := context.WithTimeout(ctx, 5*time.Second)
        defer cancel()
        if err := client.Ping(ctx2, nil); err != nil {
                return nil, err
        }
        return client, nil
}

func mongoDBName() string {
        uri := os.Getenv("MONGODB_URI")
        if uri == "" {
                return "arena"
        }
        // naive parse: last path segment
        for i := len(uri) - 1; i >= 0; i-- {
                if uri[i] == '/' {
                        name := uri[i+1:]
                        if name == "" {
                                return "arena"
                        }
                        // strip query params
                        for j := 0; j < len(name); j++ {
                                if name[j] == '?' {
                                        return name[:j]
                                }
                        }
                        return name
                }
        }
        return "arena"
}

func applyMigrations(ctx context.Context, pool *pgxpool.Pool) error {
        _, err := pool.Exec(ctx, schemaSQL)
        if err != nil {
                return fmt.Errorf("apply migrations: %w", err)
        }
        return nil
}

func ensureMongoIndexes(ctx context.Context, client *mongo.Client) (*mongo.Collection, error) {
        db := client.Database(mongoDBName())
        coll := db.Collection("audit_entries")

        names := []string{}
        cur, err := db.ListCollectionNames(ctx, map[string]interface{}{"name": "audit_entries"})
        if err == nil {
                names = cur
        }
        if len(names) == 0 {
                if err := db.CreateCollection(ctx, "audit_entries"); err != nil {
                        log.Printf("createCollection audit_entries: %v", err)
                }
        }

        indexModels := []mongo.IndexModel{
                {Keys: map[string]interface{}{"occurredAt": -1}},
                {Keys: map[string]interface{}{"actorId": 1}},
                {Keys: map[string]interface{}{"entityType": 1, "entityId": 1}},
                {Keys: map[string]interface{}{"action": 1}},
                {Keys: map[string]interface{}{"role": 1}},
                {Keys: map[string]interface{}{"success": 1}},
                {Keys: map[string]interface{}{"searchText": "text"}},
        }
        _, err = coll.Indexes().CreateMany(ctx, indexModels)
        if err != nil {
                log.Printf("mongo index creation warning: %v", err)
        }
        return coll, nil
}

