import (
	"net/http"
	"time"
)

type authenticateUserReq struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

func (app *App) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req authenticateUserReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.Username == "" || req.Password == "" {
		writeErr(w, newErr(401, "invalid_credentials", "invalid credentials"))
		return
	}
	ctx := r.Context()
	var userID, hash string
	var roles []string
	var active bool
	err := app.DB.Pool.QueryRow(ctx, `SELECT id, password_hash, roles, active FROM users WHERE username=$1`, req.Username).
		Scan(&userID, &hash, &roles, &active)
	if err != nil || !active || !verifyPassword(req.Password, hash) {
		writeErr(w, newErr(401, "invalid_credentials", "invalid credentials"))
		return
	}

	tok, sessID, err := newSession(ctx, app, userID)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
