   131		defer conn.Close()
   132	
   133		// Replay durable events since cursor first.
   134		events, cursor := app.fetchEventsSince(r.Context(), u, since, 1000)
   135		for _, ev := range events {
   136			if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
   137				return
   138			}
   139		}
