   157		for {
   158			select {
   159			case <-done:
   160				return
   161			case ev := <-ch:
   162				if ev.ID <= cursor {
   163					continue
   164				}
   165				if !app.eventVisibleTo(ev, u) {
   166					continue
   167				}
   168				if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
   169					return
   170				}
   171				cursor = ev.ID
   172			case <-ticker.C:
   173				if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
   174					return
   175				}
   176			}
