import (
	"context"
	"net/http"
	"time"
)

func (app *App) handleReady(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()

	if err := app.DB.Pool.Ping(ctx); err != nil {
		writeJSON(w, 503, map[string]interface{}{"status": "not_ready", "error": err.Error()})
		return
	}
	if app.DB.Mongo != nil {
		if err := app.DB.Mongo.Ping(ctx, nil); err != nil {
			writeJSON(w, 503, map[string]interface{}{"status": "not_ready", "error": err.Error()})
			return
		}
	}
	writeJSON(w, 200, map[string]interface{}{"status": "ready"})
}

