    89			for _, p := range parts {
    90				p = strings.TrimSpace(p)
    91				if strings.HasPrefix(p, "bearer.") {
    92					encoded := strings.TrimPrefix(p, "bearer.")
    93					if decoded, err := base64.RawURLEncoding.DecodeString(encoded); err == nil {
    94						tok = string(decoded)
    95					} else {
    96						tok = encoded
    97					}
    98				}
    99			}
   100		}
   101		if tok == "" {
   102			tok = extractBearer(r)
   103		}
