    82	func itoa(n int) string {
    83		if n == 0 {
    84			return "0"
    85		}
    86		neg := n < 0
    87		if neg {
    88			n = -n
    89		}
    90		var buf [20]byte
    91		i := len(buf)
    92		for n > 0 {
    93			i--
    94			buf[i] = byte('0' + n%10)
    95			n /= 10
    96		}
    97		if neg {
    98			i--
    99			buf[i] = '-'
   100		}
   101		return string(buf[i:])
   102	}
