    84			// connections are usable in both directions for transport purposes
    85			g.Adj[e.To] = append(g.Adj[e.To], idx)
    86		}
    87		erows.Close()
    88	
    89		lrows, err := app.DB.Pool.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
    90		if err != nil {
    91			return nil, err
    92		}
    93		for lrows.Next() {
    94			var lab, st string
    95			var accepts bool
    96			if err := lrows.Scan(&lab, &st, &accepts); err != nil {
    97				continue
    98			}
    99			if g.LabAccepts[lab] == nil {
   100				g.LabAccepts[lab] = map[string]bool{}
   101			}
   102			g.LabAccepts[lab][st] = accepts
   103		}
   104		lrows.Close()
   105	
   106		return g, nil
   107	}
   108	
   109	// --- Dijkstra ---
   110	
   111	type pqItem struct {
   112		loc      string
   113		dist     int
   114		pathEdge int // edge index used to arrive here (-1 for source)
   115		prevLoc  string
   116	}
   117	
   118	type priorityQueue []*pqItem
   119	
   120	func (pq priorityQueue) Len() int            { return len(pq) }
   121	func (pq priorityQueue) Less(i, j int) bool  { return pq[i].dist < pq[j].dist }
   122	func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
   123	func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(*pqItem)) }
   124	func (pq *priorityQueue) Pop() interface{} {
   125		old := *pq
   126		n := len(old)
   127		it := old[n-1]
   128		*pq = old[:n-1]
   129		return it
   130	}
   131	
   132	type routeResult struct {
   133		PathLocations []string // ordered location ids, including entry and destination lab
   134		PathEdges     []string // connection ids used, len = len(PathLocations)-1
   135		TotalMinutes  int
   136		LabID         string
   137	}
   138	
   139	// findRoute runs Dijkstra from entryLocationID to the nearest active, accepting laboratory,
   140	// honoring cooled-route requirements when requireCooled is true.
   141	func findRoute(g *networkGraph, entryLocationID, sampleTypeID string, requireCooled bool) *routeResult {
   142		entry, ok := g.Nodes[entryLocationID]
   143		if !ok || !entry.Active {
   144			return nil
   145		}
   146		dist := map[string]int{entryLocationID: 0}
   147		prevEdge := map[string]int{}
   148		prevLoc := map[string]string{}
   149		visited := map[string]bool{}
   150	
   151		pq := &priorityQueue{{loc: entryLocationID, dist: 0, pathEdge: -1}}
   152		heap.Init(pq)
   153	
   154		// If entry itself is an accepting active lab, trivially return it.
   155		if entry.IsLab && g.LabAccepts[entryLocationID][sampleTypeID] {
   156			return &routeResult{PathLocations: []string{entryLocationID}, PathEdges: []string{}, TotalMinutes: 0, LabID: entryLocationID}
   157		}
   158	
   159		for pq.Len() > 0 {
   160			cur := heap.Pop(pq).(*pqItem)
   161			if visited[cur.loc] {
   162				continue
   163			}
   164			visited[cur.loc] = true
   165	
   166			node := g.Nodes[cur.loc]
   167			if node != nil && node.IsLab && g.LabAccepts[cur.loc][sampleTypeID] && cur.loc != entryLocationID {
   168				// reconstruct path
   169				pathLocs := []string{}
   170				pathEdges := []string{}
   171				loc := cur.loc
   172				for {
   173					pathLocs = append([]string{loc}, pathLocs...)
   174					pe, ok := prevEdge[loc]
   175					if !ok {
   176						break
   177					}
   178					pathEdges = append([]string{g.Edges[pe].ID}, pathEdges...)
   179					loc = prevLoc[loc]
   180					if loc == entryLocationID {
   181						pathLocs = append([]string{loc}, pathLocs...)
   182						break
   183					}
   184				}
   185				return &routeResult{PathLocations: pathLocs, PathEdges: pathEdges, TotalMinutes: cur.dist, LabID: cur.loc}
   186			}
   187	
   188			for _, ei := range g.Adj[cur.loc] {
   189				e := g.Edges[ei]
   190				if !e.Active {
   191					continue
   192				}
   193				if requireCooled && !e.Cooled {
   194					continue
   195				}
   196				var next string
   197				if e.From == cur.loc {
   198					next = e.To
   199				} else if e.To == cur.loc {
   200					next = e.From
   201				} else {
   202					continue
   203				}
   204				nn := g.Nodes[next]
   205				if nn == nil || !nn.Active {
   206					continue
   207				}
   208				nd := cur.dist + e.TravelMinutes
   209				if existing, ok := dist[next]; !ok || nd < existing {
   210					dist[next] = nd
   211					prevEdge[next] = ei
   212					prevLoc[next] = cur.loc
   213					heap.Push(pq, &pqItem{loc: next, dist: nd, pathEdge: ei, prevLoc: cur.loc})
   214				}
   215			}
   216		}
   217		return nil
   218	}
   219	
   220	// findEntryLocation resolves the collection entry point for a request origin.
   221	func findEntryLocation(g *networkGraph, originType string, lat, lng float64, originNodeID string) *locNode {
   222		if originType == "node" && originNodeID != "" {
   223			n := g.Nodes[originNodeID]
   224			if n == nil || !n.Active {
   225				return nil
   226			}
   227			return n
   228		}
   229		var best *locNode
   230		bestDist := 1e18
   231		for _, n := range g.Nodes {
   232			if !n.Active || !n.IsCollection {
   233				continue
   234			}
   235			d := haversineKm(lat, lng, n.Lat, n.Lng)
   236			cov := n.CoverageKm
   237			if cov <= 0 || cov > 5 {
   238				cov = 5
   239			}
   240			if d <= cov && d < bestDist {
   241				bestDist = d
   242				best = n
   243			}
   244		}
   245		return best
   246	}
   247	
   248	// capacityCheck verifies that all nodes and edges in the given path have at least
   249	// one available unit in the required pool (regular or cooled).
   250	func capacityCheck(g *networkGraph, path []string, edges []string, cooled bool) bool {
   251		for _, locID := range path {
   252			n := g.Nodes[locID]
   253			if n == nil {
   254				return false
   255			}
   256			if cooled {
   257				if n.CooledCapacityUnits-n.CooledReservedUnits < 1 {
   258					return false
   259				}
   260			} else {
   261				if n.CapacityUnits-n.ReservedUnits < 1 {
   262					return false
   263				}
   264			}
   265		}
   266		for _, eid := range edges {
   267			for _, e := range g.Edges {
   268				if e.ID == eid {
   269					if cooled {
   270						if e.CooledCapacityUnits-e.CooledReservedUnits < 1 {
   271							return false
   272						}
   273					} else {
   274						if e.CapacityUnits-e.ReservedUnits < 1 {
   275							return false
   276						}
   277					}
   278				}
   279			}
   280		}
   281		return true
   282	}
   283	
   284	type planOutcome struct {
   285		Serviceable   bool
   286		Reason        string
   287		LabID         string
   288		EstimatedAt   time.Time
   289		PathLocations []string
   290		PathEdges     []string
   291		TotalMinutes  int
   292	}
   293	
   294	// planRoute computes a full serviceability+routing outcome without persisting anything.
   295	func (app *App) planRoute(ctx context.Context, originType string, lat, lng float64, originNodeID string,
   296		sampleTypeID string, requireCooled bool, startAt time.Time, deadline time.Time) (*planOutcome, *networkGraph, error) {
   297	
   298		g, err := app.loadNetworkGraph(ctx)
   299		if err != nil {
   300			return nil, nil, err
   301		}
   302	
   303		entry := findEntryLocation(g, originType, lat, lng, originNodeID)
   304		if entry == nil {
   305			return &planOutcome{Serviceable: false, Reason: "outside_service_coverage"}, g, nil
   306		}
   307	
   308		route := findRoute(g, entry.ID, sampleTypeID, requireCooled)
   309		if route == nil {
   310			return &planOutcome{Serviceable: false, Reason: "no_accepting_laboratory"}, g, nil
   311		}
   312	
   313		if !capacityCheck(g, route.PathLocations, route.PathEdges, requireCooled) {
   314			return &planOutcome{Serviceable: false, Reason: "insufficient_capacity"}, g, nil
   315		}
   316	
   317		// Estimate arrival time by walking the path, accumulating handling + travel minutes.
   318		t := startAt
   319		t = t.Add(time.Duration(g.Nodes[route.PathLocations[0]].HandlingMinutes) * time.Minute)
   320		for i := 1; i < len(route.PathLocations); i++ {
   321			edgeID := route.PathEdges[i-1]
   322			var mins int
   323			for _, e := range g.Edges {
   324				if e.ID == edgeID {
   325					mins = e.TravelMinutes
   326					break
   327				}
   328			}
   329			t = t.Add(time.Duration(mins) * time.Minute)
   330			t = t.Add(time.Duration(g.Nodes[route.PathLocations[i]].HandlingMinutes) * time.Minute)
   331		}
   332	
   333		if t.After(deadline) {
   334			return &planOutcome{Serviceable: false, Reason: "deadline_unreachable", LabID: route.LabID, EstimatedAt: t,
   335				PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes}, g, nil
   336		}
   337	
   338		return &planOutcome{
   339			Serviceable: true, Reason: "serviceable", LabID: route.LabID, EstimatedAt: t,
   340			PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes,
   341		}, g, nil
   342	}
   343	
   344	// reserveCapacityForJourney reserves 1 unit (regular or cooled) at every node & edge in
   345	// the path and records rows in capacity_reservations for later release.
   346	func reserveCapacityForJourney(ctx context.Context, tx pgx.Tx, journeyID, sampleID string, path []string, edges []string, cooled bool) error {
   347		for _, locID := range path {
   348			col := "reserved_units"
   349			capCol := "capacity_units"
   350			if cooled {
   351				col = "cooled_reserved_units"
   352				capCol = "cooled_capacity_units"
   353			}
   354			res, err := tx.Exec(ctx, `UPDATE locations SET `+col+` = `+col+` + 1, updated_at=now()
   355				WHERE id = $1 AND `+col+` + 1 <= `+capCol, locID)
   356			if err != nil {
   357				return err
   358			}
   359			if res.RowsAffected() == 0 {
   360				return newErr(409, "capacity_exhausted", "capacity exhausted at location "+locID)
   361			}
   362			_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'location',$3,$4,1)`,
   363				sampleID, journeyID, locID, cooled)
   364			if err != nil {
   365				return err
   366			}
   367		}
   368		for _, eid := range edges {
   369			col := "reserved_units"
   370			capCol := "capacity_units"
   371			if cooled {
   372				col = "cooled_reserved_units"
   373				capCol = "cooled_capacity_units"
   374			}
   375			res, err := tx.Exec(ctx, `UPDATE connections SET `+col+` = `+col+` + 1, updated_at=now()
   376				WHERE id = $1 AND `+col+` + 1 <= `+capCol, eid)
   377			if err != nil {
   378				return err
   379			}
   380			if res.RowsAffected() == 0 {
   381				return newErr(409, "cooled_capacity_exhausted", "capacity exhausted on connection "+eid)
   382			}
   383			_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'connection',$3,$4,1)`,
   384				sampleID, journeyID, eid, cooled)
   385			if err != nil {
   386				return err
   387			}
   388		}
   389		return nil
   390	}
   391	
   392	// releaseJourneyCapacity releases all capacity reservations tied to a journey.
   393	func releaseJourneyCapacity(ctx context.Context, tx pgx.Tx, journeyID string) error {
   394		rows, err := tx.Query(ctx, `SELECT id, pool_type, pool_id, cooled, units FROM capacity_reservations WHERE journey_id = $1 AND released = false`, journeyID)
   395		if err != nil {
   396			return err
   397		}
   398		type r struct {
   399			id       string
   400			poolType string
   401			poolID   string
   402			cooled   bool
   403			units    int
   404		}
   405		var list []r
   406		for rows.Next() {
   407			var it r
   408			if err := rows.Scan(&it.id, &it.poolType, &it.poolID, &it.cooled, &it.units); err != nil {
   409				rows.Close()
   410				return err
   411			}
   412			list = append(list, it)
   413		}
   414		rows.Close()
   415	
   416		for _, it := range list {
   417			col := "reserved_units"
   418			if it.cooled {
   419				col = "cooled_reserved_units"
   420			}
   421			table := "locations"
   422			if it.poolType == "connection" {
   423				table = "connections"
   424			}
   425			_, err := tx.Exec(ctx, `UPDATE `+table+` SET `+col+` = GREATEST(`+col+` - $1, 0), updated_at=now() WHERE id = $2`, it.units, it.poolID)
   426			if err != nil {
   427				return err
   428			}
   429			_, err = tx.Exec(ctx, `UPDATE capacity_reservations SET released = true, released_at = now() WHERE id = $1`, it.id)
   430			if err != nil {
   431				return err
   432			}
   433		}
   434		return nil
   435	}
   436

