		writeErr(w, err)
		return
	}
	if req.SampleTypeID == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeErr(w, newErr(400, "invalid_json", "sampleTypeId, containerType, temperatureMinC and temperatureMaxC are required"))
		return
	}
	if *req.TemperatureMinC > *req.TemperatureMaxC {
		writeErr(w, newErr(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC"))
		return
	}
