	if incompat == nil {
		incompat = []string{}
	}
	var requiredQual interface{}
	if req.RequiredQualification != nil && *req.RequiredQualification != "" {
		requiredQual = *req.RequiredQualification
	}

	var name string
	err := app.DB.Pool.QueryRow(ctx, `
