package main

import (
	"net/http"
)

type configureCapacityReq struct {
	ResourceID           string `json:"resourceId"`
	CapacityUnits        *int   `json:"capacityUnits"`
	CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
}

// handleConfigureCapacity configures regular/cooled capacity for a location (node or
// laboratory) or a transport connection. Administrators may configure any resource;
// node handlers and laboratory intake operators may only configure the single location
// they are assigned to.
func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req configureCapacityReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.ResourceID == "" || req.CapacityUnits == nil {
		writeErr(w, newErr(400, "invalid_capacity", "resourceId and capacityUnits are required"))
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if *req.CapacityUnits < 0 || cooled < 0 {
		writeErr(w, newErr(400, "invalid_capacity", "capacity values must be >= 0"))
		return
	}
	ctx := r.Context()

	var isLocation bool
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1`, req.ResourceID).Scan(&isLocation)

	table := "locations"
	if !isLocation {
		var isConn bool
		app.DB.Pool.QueryRow(ctx, `SELECT true FROM connections WHERE id=$1`, req.ResourceID).Scan(&isConn)
		if !isConn {
			writeErr(w, errNotFound())
