   248	// capacityCheck verifies that all nodes and edges in the given path have at least
   249	// one available unit in the required pool (regular or cooled).
   250	func capacityCheck(g *networkGraph, path []string, edges []string, cooled bool) bool {
   251		for _, locID := range path {
   252			n := g.Nodes[locID]
   253			if n == nil {
   254				return false
   255			}
   256			if cooled {
   257				if n.CooledCapacityUnits-n.CooledReservedUnits < 1 {
   258					return false
   259				}
   260			} else {
   261				if n.CapacityUnits-n.ReservedUnits < 1 {
   262					return false
   263				}
   264			}
   265		}
   266		for _, eid := range edges {
   267			for _, e := range g.Edges {
   268				if e.ID == eid {
   269					if cooled {
   270						if e.CooledCapacityUnits-e.CooledReservedUnits < 1 {
   271							return false
   272						}
   273					} else {
   274						if e.CapacityUnits-e.ReservedUnits < 1 {
   275							return false
   276						}
   277					}
   278				}
   279			}
   280		}
   281		return true
   282	}
