    83	func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
    84		// Determine auth: prefer the Sec-WebSocket-Protocol bearer, fallback to Authorization header.
    85		var tok string
    86		proto := r.Header.Get("Sec-WebSocket-Protocol")
    87		if proto != "" {
    88			parts := strings.Split(proto, ",")
    89			for _, p := range parts {
    90				p = strings.TrimSpace(p)
    91				if strings.HasPrefix(p, "bearer.") {
    92					encoded := strings.TrimPrefix(p, "bearer.")
    93					if decoded, err := base64.RawURLEncoding.DecodeString(encoded); err == nil {
    94						tok = string(decoded)
    95					} else {
    96						tok = encoded
    97					}
    98				}
    99			}
   100		}
   101		if tok == "" {
   102			tok = extractBearer(r)
   103		}
   104		u, err := app.authenticate(r.Context(), tok)
   105		if err != nil {
   106			writeErr(w, errUnauthorized())
   107			return
   108		}
   109	
   110		sinceStr := r.URL.Query().Get("since")
   111		since := int64(0)
   112		if sinceStr != "" {
   113			since, _ = strconv.ParseInt(sinceStr, 10, 64)
   114		}
   115	
   116		if websocket.IsWebSocketUpgrade(r) {
   117			app.serveWSEvents(w, r, u, since)
   118			return
   119		}
   120	
   121		// Plain HTTP polling fallback.
   122		events, cursor := app.fetchEventsSince(r.Context(), u, since, 500)
   123		writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
   124	}
