   118	// activateNextAssignment finds the earliest not-yet-offered assignment on the journey
   119	// whose predecessor assignment (by sequence) is completed, and offers it to the best
   120	// eligible available worker. If none are eligible/available, it leaves the assignment
   121	// pending (unassigned) for the sweeper to retry, and if it has been pending "long enough"
   122	// with zero eligible workers ever available it will be flagged as an exception by the
   123	// sweeper instead.
   124	func (app *App) activateNextAssignment(ctx context.Context, tx pgx.Tx, journeyID string) error {
   125		rows, err := tx.Query(ctx, `
   126			SELECT id, journey_id, kind, sequence, sample_id, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''),
   127			       COALESCE(node_id::text,''), COALESCE(laboratory_id::text,''), status, declined_worker_ids
   128			FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
   129		if err != nil {
   130			return err
   131		}
   132		var list []assignmentRow
   133		for rows.Next() {
   134			var a assignmentRow
   135			if err := rows.Scan(&a.ID, &a.JourneyID, &a.Kind, &a.Sequence, &a.SampleID, &a.FromLocID, &a.ToLocID, &a.NodeID, &a.LaboratoryID, &a.Status, &a.DeclinedIDs); err != nil {
   136				rows.Close()
   137				return err
   138			}
   139			list = append(list, a)
   140		}
   141		rows.Close()
   142	
   143		for i, a := range list {
   144			if a.Status != "pending" {
   145				continue
   146			}
   147			if i > 0 && list[i-1].Status != "completed" {
   148				break // predecessor not done yet; cannot activate this one
   149			}
   150			return app.tryOfferAssignment(ctx, tx, &a)
   151		}
   152		return nil
   153	}
   154	
   155	func (app *App) tryOfferAssignment(ctx context.Context, tx pgx.Tx, a *assignmentRow) error {
   156		locationID := a.NodeID
   157		if a.Kind == "laboratory" {
   158			locationID = a.LaboratoryID
   159		}
   160		var sampleTypeID string
   161		tx.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE id=$1`, a.SampleID).Scan(&sampleTypeID)
   162	
   163		candidates, err := app.eligibleWorkersForAssignment(ctx, tx, a.Kind, sampleTypeID, locationID, a.DeclinedIDs)
   164		if err != nil {
   165			return err
   166		}
   167		if len(candidates) == 0 {
   168			// No eligible worker right now; leave pending, sweeper will retry / flag exception.
   169			return nil
   170		}
   171		worker := candidates[0]
   172		expires := nowUTC().Add(offerTTL)
   173		_, err = tx.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$1, offer_expires_at=$2, updated_at=now() WHERE id=$3`,
   174			worker, expires, a.ID)
   175		if err != nil {
   176			return err
   177		}
   178		return nil
   179	}
