    76			if err := erows.Scan(&e.ID, &e.From, &e.To, &e.TravelMinutes, &e.CostUnits, &e.Cooled, &e.Active,
    77				&e.CapacityUnits, &e.ReservedUnits, &e.CooledCapacityUnits, &e.CooledReservedUnits); err != nil {
    78				erows.Close()
    79				return nil, err
    80			}
    81			idx := len(g.Edges)
    82			g.Edges = append(g.Edges, e)
    83			g.Adj[e.From] = append(g.Adj[e.From], idx)
    84			// connections are usable in both directions for transport purposes
    85			g.Adj[e.To] = append(g.Adj[e.To], idx)
    86		}
    87		erows.Close()
    88	
    89		lrows, err := app.DB.Pool.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
    90		if err != nil {
    91			return nil, err
    92		}
    93		for lrows.Next() {
    94			var lab, st string
    95			var accepts bool
    96			if err := lrows.Scan(&lab, &st, &accepts); err != nil {
    97				continue
    98			}
    99			if g.LabAccepts[lab] == nil {
   100				g.LabAccepts[lab] = map[string]bool{}
   101			}
   102			g.LabAccepts[lab][st] = accepts
   103		}
   104		lrows.Close()
