   184	func (app *App) fetchEventsSince(ctx context.Context, u *AuthedUser, since int64, limit int) ([]RealtimeEvent, int64) {
   185		rows, err := app.DB.Pool.Query(ctx, `
   186			SELECT id, type, entity_type, entity_id, payload, created_at, COALESCE(audience_role,''), COALESCE(audience_user_id::text,'')
   187			FROM realtime_events
   188			WHERE id > $1
   189			  AND (audience_role IS NULL OR audience_role = $2)
   190			  AND (audience_user_id IS NULL OR audience_user_id = $3::uuid)
   191			ORDER BY id ASC LIMIT $4`, since, u.ActiveRole, u.UserID, limit)
   192		if err != nil {
   193			return []RealtimeEvent{}, since
   194		}
   195		defer rows.Close()
   196		out := []RealtimeEvent{}
   197		cursor := since
   198		for rows.Next() {
   199			var ev RealtimeEvent
   200			var payloadRaw []byte
   201			var audRole, audUser string
   202			if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityID, &payloadRaw, &ev.CreatedAt, &audRole, &audUser); err != nil {
   203				continue
   204			}
   205			_ = json.Unmarshal(payloadRaw, &ev.Payload)
   206			out = append(out, ev)
   207			if ev.ID > cursor {
   208				cursor = ev.ID
   209			}
   210		}
   211		return out, cursor
   212	}
