     7	type configureCapacityReq struct {
     8		ResourceID           string `json:"resourceId"`
     9		CapacityUnits        *int   `json:"capacityUnits"`
    10		CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
    11	}
    12	
    13	// handleConfigureCapacity configures regular/cooled capacity for a location (node or
    14	// laboratory) or a transport connection. Administrators may configure any resource;
    15	// node handlers and laboratory intake operators may only configure the single location
    16	// they are assigned to.
    17	func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
    18		if r.Method != http.MethodPost {
    19			writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
    20			return
    21		}
    22		var req configureCapacityReq
    23		if err := decodeJSONBody(r, &req); err != nil {
    24			writeErr(w, err)
    25			return
    26		}
    27		if req.ResourceID == "" || req.CapacityUnits == nil {
    28			writeErr(w, newErr(400, "invalid_capacity", "resourceId and capacityUnits are required"))
    29			return
    30		}
    31		cooled := 0
    32		if req.CooledCapacityUnits != nil {
    33			cooled = *req.CooledCapacityUnits
    34		}
    35		if *req.CapacityUnits < 0 || cooled < 0 {
    36			writeErr(w, newErr(400, "invalid_capacity", "capacity values must be >= 0"))
    37			return
    38		}
    39		ctx := r.Context()
    40	
    41		var isLocation bool
    42		app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1`, req.ResourceID).Scan(&isLocation)
    43	
    44		table := "locations"
    45		if !isLocation {
    46			var isConn bool
    47			app.DB.Pool.QueryRow(ctx, `SELECT true FROM connections WHERE id=$1`, req.ResourceID).Scan(&isConn)
    48			if !isConn {
    49				writeErr(w, errNotFound())
    50				return
    51			}
    52			table = "connections"
    53		}
    54	
    55		if (u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam) && table == "locations" {
    56			if u.AssignedLocationID != req.ResourceID {
    57				writeErr(w, errForbidden())
    58				return
    59			}
    60		} else if u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
    61			writeErr(w, errForbidden())
    62			return
    63		}
    64	
    65		var reserved, cooledReserved int
    66		app.DB.Pool.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM `+table+` WHERE id=$1`, req.ResourceID).Scan(&reserved, &cooledReserved)
    67		if *req.CapacityUnits < reserved || cooled < cooledReserved {
    68			writeErr(w, newErr(409, "capacity_reserved", "capacity cannot be reduced below currently reserved units"))
    69			return
    70		}
    71	
    72		_, err := app.DB.Pool.Exec(ctx, `UPDATE `+table+` SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3`,
    73			*req.CapacityUnits, cooled, req.ResourceID)
    74		if err != nil {
    75			writeErr(w, errInternal(err.Error()))
    76			return
    77		}
    78	
    79		app.recordAction(ctx, u.UserID, u.ActiveRole, "configure_capacity", table, req.ResourceID, "", true,
    80			map[string]interface{}{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
    81		if table == "locations" {
    82			app.recomputeServiceabilitySnapshot(ctx)
    83		}
    84	
    85		writeData(w, 200, map[string]interface{}{
    86			"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled,
    87		})
    88	}
    89	
    90	type configureLaboratoryAcceptanceReq struct {
