    92		SampleTypeID string `json:"sampleTypeId"`
    93		Accepts      *bool  `json:"accepts"`
    94	}
    95	
    96	func (app *App) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
    97		if r.Method != http.MethodPost {
    98			writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
    99			return
   100		}
   101		var req configureLaboratoryAcceptanceReq
