   113		app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1 AND is_laboratory`, req.LaboratoryID).Scan(&labExists)
   114		app.DB.Pool.QueryRow(ctx, `SELECT true FROM sample_types WHERE id=$1`, req.SampleTypeID).Scan(&stExists)
   115		if !labExists || !stExists {
   116			writeErr(w, newErr(400, "invalid_acceptance", "laboratoryId must be an active laboratory location and sampleTypeId must exist"))
   117			return
   118		}
