     1	package main
     2	
     3	import (
     4		"context"
     5		"time"
     6	
     7		"github.com/jackc/pgx/v5"
     8	)
     9	
    10	const offerTTL = 2 * time.Minute
    11	
    12	// eligibleWorkersForAssignment returns candidate worker ids/roles for the given
    13	// assignment kind, respecting qualification (for collection), and node/lab assignment.
    14	func (app *App) eligibleWorkersForAssignment(ctx context.Context, tx pgx.Tx, kind, sampleTypeID, locationID string, declinedIDs []string) ([]string, error) {
    15		var role string
    16		switch kind {
    17		case "collection":
    18			role = RoleCollectionProfessional
    19		case "transport":
    20			role = RoleDeliveryPartner
    21		case "node":
    22			role = RoleNodeHandler
    23		case "laboratory":
    24			role = RoleLaboratoryTeam
    25		default:
    26			return nil, nil
    27		}
    28	
    29		query := `
    30			SELECT u.id FROM users u
    31			LEFT JOIN worker_stats ws ON ws.worker_id = u.id
    32			WHERE u.active = true AND $1 = ANY(u.roles)
    33		`
    34		args := []interface{}{role}
    35		argN := 2
    36	
    37		if kind == "node" || kind == "laboratory" {
    38			query += ` AND u.assigned_location_id = $` + itoa(argN)
    39			args = append(args, locationID)
    40			argN++
    41		}
    42	
    43		if kind == "collection" && sampleTypeID != "" {
    44			query += ` AND EXISTS (
    45				SELECT 1 FROM sample_types st WHERE st.id = $` + itoa(argN) + `
    46				AND (st.required_qualification IS NULL OR st.required_qualification = ANY(u.qualifications))
    47			)`
    48			args = append(args, sampleTypeID)
    49			argN++
    50		}
    51	
    52		query += ` AND COALESCE(ws.available, true) = true`
    53		query += ` ORDER BY COALESCE(ws.assignment_count,0) ASC,
    54			CASE WHEN ws.last_decline_at IS NOT NULL AND ws.last_decline_at > now() - interval '10 minutes' THEN 1 ELSE 0 END ASC,
    55			u.created_at ASC`
    56	
    57		rows, err := tx.Query(ctx, query, args...)
    58		if err != nil {
    59			return nil, err
    60		}
    61		defer rows.Close()
    62		var out []string
    63		for rows.Next() {
    64			var id string
    65			if err := rows.Scan(&id); err != nil {
    66				continue
    67			}
    68			skip := false
    69			for _, d := range declinedIDs {
    70				if d == id {
    71					skip = true
    72					break
    73				}
    74			}
    75			if !skip {
    76				out = append(out, id)
    77			}
    78		}
    79		return out, nil
    80	}
    81	
    82	func itoa(n int) string {
    83		if n == 0 {
    84			return "0"
    85		}
    86		neg := n < 0
    87		if neg {
    88			n = -n
    89		}
    90		var buf [20]byte
    91		i := len(buf)
    92		for n > 0 {
    93			i--
    94			buf[i] = byte('0' + n%10)
    95			n /= 10
    96		}
    97		if neg {
    98			i--
    99			buf[i] = '-'
   100		}
   101		return string(buf[i:])
   102	}
   103	
   104	type assignmentRow struct {
   105		ID           string
   106		JourneyID    string
   107		Kind         string
   108		Sequence     int
   109		SampleID     string
   110		FromLocID    string
   111		ToLocID      string
   112		NodeID       string
   113		LaboratoryID string
   114		Status       string
   115		DeclinedIDs  []string
   116	}
   117	
   118	// activateNextAssignment finds the earliest not-yet-offered assignment on the journey
   119	// whose predecessor assignment (by sequence) is completed, and offers it to the best
   120	// eligible available worker. If none are eligible/available, it leaves the assignment
   121	// pending (unassigned) for the sweeper to retry, and if it has been pending "long enough"
   122	// with zero eligible workers ever available it will be flagged as an exception by the
   123	// sweeper instead.
   124	func (app *App) activateNextAssignment(ctx context.Context, tx pgx.Tx, journeyID string) error {
   125		rows, err := tx.Query(ctx, `
   126			SELECT id, journey_id, kind, sequence, sample_id, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''),
   127			       COALESCE(node_id::text,''), COALESCE(laboratory_id::text,''), status, declined_worker_ids
   128			FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
   129		if err != nil {
   130			return err
   131		}
   132		var list []assignmentRow
   133		for rows.Next() {
   134			var a assignmentRow
   135			if err := rows.Scan(&a.ID, &a.JourneyID, &a.Kind, &a.Sequence, &a.SampleID, &a.FromLocID, &a.ToLocID, &a.NodeID, &a.LaboratoryID, &a.Status, &a.DeclinedIDs); err != nil {
   136				rows.Close()
   137				return err
   138			}
   139			list = append(list, a)
   140		}
   141		rows.Close()
   142	
   143		for i, a := range list {
   144			if a.Status != "pending" {
   145				continue
   146			}
   147			if i > 0 && list[i-1].Status != "completed" {
   148				break // predecessor not done yet; cannot activate this one
   149			}
   150			return app.tryOfferAssignment(ctx, tx, &a)
   151		}
   152		return nil
   153	}
   154	
   155	func (app *App) tryOfferAssignment(ctx context.Context, tx pgx.Tx, a *assignmentRow) error {
   156		locationID := a.NodeID
   157		if a.Kind == "laboratory" {
   158			locationID = a.LaboratoryID
   159		}
   160		var sampleTypeID string
   161		tx.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE id=$1`, a.SampleID).Scan(&sampleTypeID)
   162	
   163		candidates, err := app.eligibleWorkersForAssignment(ctx, tx, a.Kind, sampleTypeID, locationID, a.DeclinedIDs)
   164		if err != nil {
   165			return err
   166		}
   167		if len(candidates) == 0 {
   168			// No eligible worker right now; leave pending, sweeper will retry / flag exception.
   169			return nil
   170		}
   171		worker := candidates[0]
   172		expires := nowUTC().Add(offerTTL)
   173		_, err = tx.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$1, offer_expires_at=$2, updated_at=now() WHERE id=$3`,
   174			worker, expires, a.ID)
   175		if err != nil {
   176			return err
   177		}
   178		return nil
   179	}
