   108	
   109	// --- Dijkstra ---
   110	
   111	type pqItem struct {
   112		loc      string
   113		dist     int
   114		pathEdge int // edge index used to arrive here (-1 for source)
   115		prevLoc  string
   116	}
   117	
   118	type priorityQueue []*pqItem
   119	
   120	func (pq priorityQueue) Len() int            { return len(pq) }
   121	func (pq priorityQueue) Less(i, j int) bool  { return pq[i].dist < pq[j].dist }
   122	func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
   123	func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(*pqItem)) }
   124	func (pq *priorityQueue) Pop() interface{} {
   125		old := *pq
   126		n := len(old)
   127		it := old[n-1]
   128		*pq = old[:n-1]
   129		return it
   130	}
   131	
   132	type routeResult struct {
   133		PathLocations []string // ordered location ids, including entry and destination lab
   134		PathEdges     []string // connection ids used, len = len(PathLocations)-1
   135		TotalMinutes  int
   136		LabID         string
   137	}
   138	
   139	// findRoute runs Dijkstra from entryLocationID to the nearest active, accepting laboratory,
   140	// honoring cooled-route requirements when requireCooled is true.
   141	func findRoute(g *networkGraph, entryLocationID, sampleTypeID string, requireCooled bool) *routeResult {
   142		entry, ok := g.Nodes[entryLocationID]
   143		if !ok || !entry.Active {
   144			return nil
   145		}
   146		dist := map[string]int{entryLocationID: 0}
   147		prevEdge := map[string]int{}
   148		prevLoc := map[string]string{}
   149		visited := map[string]bool{}
   150	
   151		pq := &priorityQueue{{loc: entryLocationID, dist: 0, pathEdge: -1}}
   152		heap.Init(pq)
   153	
   154		// If entry itself is an accepting active lab, trivially return it.
   155		if entry.IsLab && g.LabAccepts[entryLocationID][sampleTypeID] {
   156			return &routeResult{PathLocations: []string{entryLocationID}, PathEdges: []string{}, TotalMinutes: 0, LabID: entryLocationID}
   157		}
   158	
   159		for pq.Len() > 0 {
   160			cur := heap.Pop(pq).(*pqItem)
   161			if visited[cur.loc] {
   162				continue
   163			}
   164			visited[cur.loc] = true
   165	
   166			node := g.Nodes[cur.loc]
   167			if node != nil && node.IsLab && g.LabAccepts[cur.loc][sampleTypeID] && cur.loc != entryLocationID {
   168				// reconstruct path
   169				pathLocs := []string{}
   170				pathEdges := []string{}
   171				loc := cur.loc
   172				for {
   173					pathLocs = append([]string{loc}, pathLocs...)
   174					pe, ok := prevEdge[loc]
   175					if !ok {
   176						break
   177					}
   178					pathEdges = append([]string{g.Edges[pe].ID}, pathEdges...)
   179					loc = prevLoc[loc]
   180					if loc == entryLocationID {
   181						pathLocs = append([]string{loc}, pathLocs...)
   182						break
   183					}
   184				}
   185				return &routeResult{PathLocations: pathLocs, PathEdges: pathEdges, TotalMinutes: cur.dist, LabID: cur.loc}
   186			}
   187	
   188			for _, ei := range g.Adj[cur.loc] {
   189				e := g.Edges[ei]
   190				if !e.Active {
   191					continue
   192				}
   193				if requireCooled && !e.Cooled {
   194					continue
   195				}
   196				var next string
   197				if e.From == cur.loc {
   198					next = e.To
   199				} else if e.To == cur.loc {
   200					next = e.From
   201				} else {
   202					continue
   203				}
   204				nn := g.Nodes[next]
   205				if nn == nil || !nn.Active {
   206					continue
   207				}
   208				nd := cur.dist + e.TravelMinutes
   209				if existing, ok := dist[next]; !ok || nd < existing {
   210					dist[next] = nd
   211					prevEdge[next] = ei
   212					prevLoc[next] = cur.loc
   213					heap.Push(pq, &pqItem{loc: next, dist: nd, pathEdge: ei, prevLoc: cur.loc})
   214				}
   215			}
   216		}
   217		return nil
   218	}
