   126	func (app *App) serveWSEvents(w http.ResponseWriter, r *http.Request, u *AuthedUser, since int64) {
   127		conn, err := wsUpgrader.Upgrade(w, r, nil)
   128		if err != nil {
   129			return
   130		}
   131		defer conn.Close()
   132	
   133		// Replay durable events since cursor first.
   134		events, cursor := app.fetchEventsSince(r.Context(), u, since, 1000)
   135		for _, ev := range events {
   136			if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
   137				return
   138			}
   139		}
   140	
   141		ch := app.events.subscribe()
   142		defer app.events.unsubscribe(ch)
   143	
   144		done := make(chan struct{})
   145		go func() {
   146			defer close(done)
   147			for {
   148				if _, _, err := conn.ReadMessage(); err != nil {
   149					return
   150				}
   151			}
   152		}()
   153	
   154		ticker := time.NewTicker(30 * time.Second)
   155		defer ticker.Stop()
   156	
   157		for {
   158			select {
   159			case <-done:
   160				return
   161			case ev := <-ch:
   162				if ev.ID <= cursor {
   163					continue
   164				}
   165				if !app.eventVisibleTo(ev, u) {
   166					continue
   167				}
   168				if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
   169					return
   170				}
   171				cursor = ev.ID
   172			case <-ticker.C:
   173				if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
   174					return
   175				}
   176			}
   177		}
   178	}
