    68	
    69	func loadSampleTimeline(ctx context.Context, app *App, sampleID string) []TimelineEntry {
    70		rows, err := app.DB.Pool.Query(ctx, `
    71			SELECT id, action, COALESCE(actor_id::text,''), COALESCE(role,''), COALESCE(entity_type,''), COALESCE(entity_id,''), success, details, occurred_at
    72			FROM sample_timeline WHERE sample_id = $1 ORDER BY id ASC`, sampleID)
    73		out := []TimelineEntry{}
    74		if err != nil {
    75			return out
    76		}
    77		defer rows.Close()
    78		for rows.Next() {
    79			var te TimelineEntry
    80			var details []byte
    81			if err := rows.Scan(&te.EventID, &te.Action, &te.ActorID, &te.Role, &te.EntityType, &te.EntityID, &te.Success, &details, &te.OccurredAt); err != nil {
    82				continue
    83			}
    84			te.Details = fromJSONB(details)
    85			out = append(out, te)
    86		}
    87		return out
    88	}
