        if 'requestBody' in op:
            try:
                entry['requestSchema']=op['requestBody']['content']['application/json']['schema']
            except Exception as e:
                entry['requestSchema']=str(e)
        if 'parameters' in op and op['parameters']:
            entry['parameters']=op['parameters']
        success={}
        errs={}
        for code,resp in op.get('responses',{}).items():
            try:
                sch=resp['content']['application/json']['schema']
            except Exception:
                sch=None
            if code.startswith('2'):
                success[code]=sch
            else:
                # just grab error codes list
                try:
                    errs[code]=sch['properties']['code']['enum']
                except Exception:
                    errs[code]=sch
        entry['success']=success
        entry['errors']=errs
        out.append(entry)
json.dump(out, open('/tmp/allops.json','w'), indent=2)
print(len(out))
EOF

