   118	type priorityQueue []*pqItem
   119	
   120	func (pq priorityQueue) Len() int            { return len(pq) }
   121	func (pq priorityQueue) Less(i, j int) bool  { return pq[i].dist < pq[j].dist }
   122	func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
   123	func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(*pqItem)) }
   124	func (pq *priorityQueue) Pop() interface{} {
   125		old := *pq
