   294	// planRoute computes a full serviceability+routing outcome without persisting anything.
   295	func (app *App) planRoute(ctx context.Context, originType string, lat, lng float64, originNodeID string,
   296		sampleTypeID string, requireCooled bool, startAt time.Time, deadline time.Time) (*planOutcome, *networkGraph, error) {
   297	
   298		g, err := app.loadNetworkGraph(ctx)
   299		if err != nil {
   300			return nil, nil, err
   301		}
   302	
   303		entry := findEntryLocation(g, originType, lat, lng, originNodeID)
   304		if entry == nil {
   305			return &planOutcome{Serviceable: false, Reason: "outside_service_coverage"}, g, nil
   306		}
   307	
   308		route := findRoute(g, entry.ID, sampleTypeID, requireCooled)
   309		if route == nil {
   310			return &planOutcome{Serviceable: false, Reason: "no_accepting_laboratory"}, g, nil
   311		}
   312	
   313		if !capacityCheck(g, route.PathLocations, route.PathEdges, requireCooled) {
   314			return &planOutcome{Serviceable: false, Reason: "insufficient_capacity"}, g, nil
   315		}
   316	
   317		// Estimate arrival time by walking the path, accumulating handling + travel minutes.
   318		t := startAt
   319		t = t.Add(time.Duration(g.Nodes[route.PathLocations[0]].HandlingMinutes) * time.Minute)
   320		for i := 1; i < len(route.PathLocations); i++ {
   321			edgeID := route.PathEdges[i-1]
   322			var mins int
   323			for _, e := range g.Edges {
   324				if e.ID == edgeID {
   325					mins = e.TravelMinutes
   326					break
   327				}
   328			}
   329			t = t.Add(time.Duration(mins) * time.Minute)
   330			t = t.Add(time.Duration(g.Nodes[route.PathLocations[i]].HandlingMinutes) * time.Minute)
   331		}
   332	
   333		if t.After(deadline) {
   334			return &planOutcome{Serviceable: false, Reason: "deadline_unreachable", LabID: route.LabID, EstimatedAt: t,
   335				PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes}, g, nil
   336		}
   337	
   338		return &planOutcome{
   339			Serviceable: true, Reason: "serviceable", LabID: route.LabID, EstimatedAt: t,
   340			PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes,
   341		}, g, nil
   342	}
