    11	// Because computation happens inside its own read of the DB and only the pointer flip
    12	// at the end is visible, any reader concurrently calling read-serviceability-snapshot
    13	// keeps seeing the previous complete version until this finishes.
    14	func (app *App) recomputeServiceabilitySnapshot(ctx context.Context) error {
    15		app.svcMu.Lock()
    16		defer app.svcMu.Unlock()
    17	
    18		g, err := app.loadNetworkGraph(ctx)
    19		if err != nil {
    20			return err
    21		}
    22	
    23		regions := []ServiceabilityRegion{}
    24		activeCount := 0
    25		for _, n := range g.Nodes {
    26			if !n.Active || !n.IsCollection {
    27				continue
    28			}
    29			activeCount++
    30			cov := n.CoverageKm
    31			if cov <= 0 || cov > 5 {
    32				cov = 5
    33			}
    34			regions = append(regions, ServiceabilityRegion{
    35				LocationID: n.ID, Name: n.Name, Latitude: n.Lat, Longitude: n.Lng, CoverageKm: cov,
    36			})
    37		}
    38	
    39		var networkRevision int
    40		err = app.DB.Pool.QueryRow(ctx, `UPDATE network_state SET network_revision = network_revision + 1 WHERE id=1 RETURNING network_revision`).Scan(&networkRevision)
    41		if err != nil {
    42			return err
    43		}
    44	
    45		version := networkRevision
    46		_, err = app.DB.Pool.Exec(ctx, `
    47			INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
    48			VALUES ($1,'complete', now(), $2, $3, $4)
    49			ON CONFLICT (version) DO UPDATE SET status='complete', computed_at=now(), network_revision=$2, regions=$3, active_collection_point_count=$4`,
    50			version, networkRevision, toJSONB(regions), activeCount)
    51		if err != nil {
    52			return err
    53		}
    54	
    55		_, err = app.DB.Pool.Exec(ctx, `UPDATE network_state SET current_snapshot_version=$1 WHERE id=1`, version)
