func idempotencySave(ctx context.Context, app *App, key, endpoint, userID, reqHash string, status int, body interface{}) {
	if key == "" {
		return
	}
	b, _ := json.Marshal(body)
	_, _ = app.DB.Pool.Exec(ctx, `
		INSERT INTO idempotency_keys (key, endpoint, user_id, request_hash, response_status, response_body)
		VALUES ($1,$2,$3,$4,$5,$6)
		ON CONFLICT (key, endpoint, user_id) DO NOTHING`,
		key, endpoint, userID, reqHash, status, b)
}

// idempotencyReplay wraps the common "check for a prior identical call" flow used by
// nearly every mutating endpoint. If a prior call is replayed, handled=true and the
// caller must return immediately (the response has already been written). If the key
// was reused with a different payload, handled=true and an idempotency_conflict error
// has already been written. Otherwise handled=false and hash should be passed to
// idempotencySaveResult once the operation succeeds.
func idempotencyReplay(w http.ResponseWriter, ctx context.Context, app *App, endpoint, userID, key string, req interface{}) (hash string, handled bool) {
	if key == "" {
		writeErr(w, errIdempotencyRequired())
		return "", true
	}
	hash = hashRequest(req)
	status, body, found, conflict := idempotencyLookup(ctx, app, key, endpoint, userID, hash)
	if conflict {
		writeErr(w, errIdempotencyConflict())
		return "", true
	}
	if found {
		writeJSON(w, status, body)
		return "", true
	}
	return hash, false
}

func idempotencySaveResult(ctx context.Context, app *App, endpoint, userID, key, hash string, status int, data interface{}) {
	idempotencySave(ctx, app, key, endpoint, userID, hash, status, map[string]interface{}{"data": data})
}

