    11	
    12	// eligibleWorkersForAssignment returns candidate worker ids/roles for the given
    13	// assignment kind, respecting qualification (for collection), and node/lab assignment.
    14	func (app *App) eligibleWorkersForAssignment(ctx context.Context, tx pgx.Tx, kind, sampleTypeID, locationID string, declinedIDs []string) ([]string, error) {
    15		var role string
    16		switch kind {
    17		case "collection":
    18			role = RoleCollectionProfessional
    19		case "transport":
    20			role = RoleDeliveryPartner
    21		case "node":
    22			role = RoleNodeHandler
    23		case "laboratory":
    24			role = RoleLaboratoryTeam
    25		default:
    26			return nil, nil
    27		}
    28	
    29		query := `
    30			SELECT u.id FROM users u
    31			LEFT JOIN worker_stats ws ON ws.worker_id = u.id
    32			WHERE u.active = true AND $1 = ANY(u.roles)
    33		`
    34		args := []interface{}{role}
    35		argN := 2
    36	
    37		if kind == "node" || kind == "laboratory" {
    38			query += ` AND u.assigned_location_id = $` + itoa(argN)
    39			args = append(args, locationID)
    40			argN++
    41		}
    42	
    43		if kind == "collection" && sampleTypeID != "" {
    44			query += ` AND EXISTS (
    45				SELECT 1 FROM sample_types st WHERE st.id = $` + itoa(argN) + `
    46				AND (st.required_qualification IS NULL OR st.required_qualification = ANY(u.qualifications))
    47			)`
    48			args = append(args, sampleTypeID)
    49			argN++
    50		}
    51	
    52		query += ` AND COALESCE(ws.available, true) = true`
    53		query += ` ORDER BY COALESCE(ws.assignment_count,0) ASC,
    54			CASE WHEN ws.last_decline_at IS NOT NULL AND ws.last_decline_at > now() - interval '10 minutes' THEN 1 ELSE 0 END ASC,
    55			u.created_at ASC`
    56	
    57		rows, err := tx.Query(ctx, query, args...)
    58		if err != nil {
    59			return nil, err
    60		}
    61		defer rows.Close()
    62		var out []string
    63		for rows.Next() {
    64			var id string
    65			if err := rows.Scan(&id); err != nil {
    66				continue
    67			}
    68			skip := false
    69			for _, d := range declinedIDs {
    70				if d == id {
    71					skip = true
    72					break
    73				}
    74			}
    75			if !skip {
    76				out = append(out, id)
    77			}
    78		}
    79		return out, nil
