   220	// findEntryLocation resolves the collection entry point for a request origin.
   221	func findEntryLocation(g *networkGraph, originType string, lat, lng float64, originNodeID string) *locNode {
   222		if originType == "node" && originNodeID != "" {
   223			n := g.Nodes[originNodeID]
   224			if n == nil || !n.Active {
   225				return nil
   226			}
   227			return n
   228		}
   229		var best *locNode
   230		bestDist := 1e18
   231		for _, n := range g.Nodes {
   232			if !n.Active || !n.IsCollection {
   233				continue
   234			}
   235			d := haversineKm(lat, lng, n.Lat, n.Lng)
   236			cov := n.CoverageKm
   237			if cov <= 0 || cov > 5 {
   238				cov = 5
   239			}
   240			if d <= cov && d < bestDist {
   241				bestDist = d
   242				best = n
   243			}
   244		}
   245		return best
   246	}
