   344	// reserveCapacityForJourney reserves 1 unit (regular or cooled) at every node & edge in
   345	// the path and records rows in capacity_reservations for later release.
   346	func reserveCapacityForJourney(ctx context.Context, tx pgx.Tx, journeyID, sampleID string, path []string, edges []string, cooled bool) error {
   347		for _, locID := range path {
   348			col := "reserved_units"
   349			capCol := "capacity_units"
   350			if cooled {
   351				col = "cooled_reserved_units"
   352				capCol = "cooled_capacity_units"
   353			}
   354			res, err := tx.Exec(ctx, `UPDATE locations SET `+col+` = `+col+` + 1, updated_at=now()
   355				WHERE id = $1 AND `+col+` + 1 <= `+capCol, locID)
   356			if err != nil {
   357				return err
   358			}
   359			if res.RowsAffected() == 0 {
   360				return newErr(409, "capacity_exhausted", "capacity exhausted at location "+locID)
   361			}
   362			_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'location',$3,$4,1)`,
   363				sampleID, journeyID, locID, cooled)
   364			if err != nil {
   365				return err
   366			}
   367		}
   368		for _, eid := range edges {
   369			col := "reserved_units"
   370			capCol := "capacity_units"
   371			if cooled {
   372				col = "cooled_reserved_units"
   373				capCol = "cooled_capacity_units"
   374			}
   375			res, err := tx.Exec(ctx, `UPDATE connections SET `+col+` = `+col+` + 1, updated_at=now()
   376				WHERE id = $1 AND `+col+` + 1 <= `+capCol, eid)
   377			if err != nil {
   378				return err
   379			}
   380			if res.RowsAffected() == 0 {
   381				return newErr(409, "cooled_capacity_exhausted", "capacity exhausted on connection "+eid)
   382			}
   383			_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'connection',$3,$4,1)`,
   384				sampleID, journeyID, eid, cooled)
   385			if err != nil {
   386				return err
   387			}
   388		}
   389		return nil
   390	}
   391	
   392	// releaseJourneyCapacity releases all capacity reservations tied to a journey.
   393	func releaseJourneyCapacity(ctx context.Context, tx pgx.Tx, journeyID string) error {
   394		rows, err := tx.Query(ctx, `SELECT id, pool_type, pool_id, cooled, units FROM capacity_reservations WHERE journey_id = $1 AND released = false`, journeyID)
   395		if err != nil {
   396			return err
   397		}
   398		type r struct {
   399			id       string
   400			poolType string
   401			poolID   string
   402			cooled   bool
   403			units    int
   404		}
   405		var list []r
   406		for rows.Next() {
   407			var it r
   408			if err := rows.Scan(&it.id, &it.poolType, &it.poolID, &it.cooled, &it.units); err != nil {
   409				rows.Close()
   410				return err
   411			}
   412			list = append(list, it)
   413		}
   414		rows.Close()
   415	
   416		for _, it := range list {
   417			col := "reserved_units"
   418			if it.cooled {
   419				col = "cooled_reserved_units"
   420			}
   421			table := "locations"
   422			if it.poolType == "connection" {
   423				table = "connections"
   424			}
   425			_, err := tx.Exec(ctx, `UPDATE `+table+` SET `+col+` = GREATEST(`+col+` - $1, 0), updated_at=now() WHERE id = $2`, it.units, it.poolID)
   426			if err != nil {
   427				return err
   428			}
   429			_, err = tx.Exec(ctx, `UPDATE capacity_reservations SET released = true, released_at = now() WHERE id = $1`, it.id)
   430			if err != nil {
   431				return err
   432			}
   433		}
   434		return nil
   435	}
