cd /workspace && python3 << 'EOF'
import json
d = json.load(open('contracts/openapi.contract.json'))
paths = d['paths']

def summarize_schema(schema, depth=0):
    if not schema:
        return None
    if '$ref' in schema:
        return {'$ref': schema['$ref']}
    if 'allOf' in schema:
        return {'allOf': [summarize_schema(s) for s in schema['allOf']]}
    t = schema.get('type')
    if t == 'object':
        props = schema.get('properties', {})
        req = schema.get('required', [])
        out = {}
        for k, v in props.items():
            out[k] = summarize_schema(v, depth+1) if depth < 3 else v.get('type')
        return {'required': req, 'properties': out}
    if t == 'array':
        return {'array_of': summarize_schema(schema.get('items', {}), depth+1)}
    return {'type': t, **({'enum': schema['enum']} if 'enum' in schema else {})}

for p, methods in paths.items():
    for method, op in methods.items():
        opid = op.get('operationId')
        sec = op.get('security', 'inherit')
        print("="*80)
        print(method.upper(), p, "->", opid, "security:", sec)
        rb = op.get('requestBody')
        if rb:
            schema = rb['content']['application/json']['schema']
            print(" REQUEST:", json.dumps(summarize_schema(schema)))
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content')
            if content:
                schema = content['application/json']['schema']
                print(f" RESP {code}:", json.dumps(summarize_schema(schema)))
            else:
                print(f" RESP {code}: (no content)")
        params = op.get('parameters')
        if params:
            print(" PARAMS:", json.dumps(params))
EOF

