import json
d = json.load(open('/workspace/contracts/openapi.contract.json'))
paths = d['paths']

def summarize_schema(s, depth=0):
    if not isinstance(s, dict):
        return str(s)
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = s.get('properties', {})
        req = s.get('required', [])
        parts = []
        for k, v in props.items():
            mark = '*' if k in req else ''
            parts.append(f"{k}{mark}:{summarize_schema(v, depth+1)}")
        return "{" + ",".join(parts) + "}"
    if t == 'array':
        return "[" + summarize_schema(s.get('items', {}), depth+1) + "]"
    if 'enum' in s:
        return f"{t}enum{s['enum']}"
    if 'oneOf' in s:
        return "oneOf[" + ",".join(summarize_schema(x, depth+1) for x in s['oneOf']) + "]"
    if 'allOf' in s:
        return "allOf[" + ",".join(summarize_schema(x, depth+1) for x in s['allOf']) + "]"
    return str(t)

for p, methods in sorted(paths.items()):
    for m, op in methods.items():
        if not isinstance(op, dict) or 'operationId' not in op:
            continue
        print("="*100)
        print(f"{m.upper()} {p}  [{op['operationId']}]")
        if 'description' in op:
            print("DESC:", op['description'][:200])
        params = op.get('parameters', [])
        if params:
            print("PARAMS:", [(pp.get('name'), pp.get('in'), pp.get('required')) for pp in params])
        rb = op.get('requestBody')
        if rb:
            content = rb.get('content', {}).get('application/json', {})
            schema = content.get('schema', {})
            print("REQUEST:", summarize_schema(schema))
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content', {}).get('application/json', {})
            schema = content.get('schema', {})
            print(f"RESP {code}:", summarize_schema(schema))

