   112		if sinceStr != "" {
   113			since, _ = strconv.ParseInt(sinceStr, 10, 64)
   114		}
   115	
   116		if websocket.IsWebSocketUpgrade(r) {
   117			app.serveWSEvents(w, r, u, since)
   118			return
   119		}
   120	
   121		// Plain HTTP polling fallback.
   122		events, cursor := app.fetchEventsSince(r.Context(), u, since, 500)
   123		writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
   124	}
   125	
   126	func (app *App) serveWSEvents(w http.ResponseWriter, r *http.Request, u *AuthedUser, since int64) {
   127		conn, err := wsUpgrader.Upgrade(w, r, nil)
   128		if err != nil {
   129			return
   130		}
   131		defer conn.Close()
   132	
   133		// Replay durable events since cursor first.
   134		events, cursor := app.fetchEventsSince(r.Context(), u, since, 1000)
   135		for _, ev := range events {
   136			if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
   137				return
   138			}
   139		}
   140	
   141		ch := app.events.subscribe()
   142		defer app.events.unsubscribe(ch)
   143	
   144		done := make(chan struct{})
   145		go func() {
   146			defer close(done)
   147			for {
   148				if _, _, err := conn.ReadMessage(); err != nil {
   149					return
   150				}
   151			}
   152		}()
   153	
   154		ticker := time.NewTicker(30 * time.Second)
   155		defer ticker.Stop()
   156	
   157		for {
   158			select {
   159			case <-done:
   160				return
   161			case ev := <-ch:
   162				if ev.ID <= cursor {
   163					continue
   164				}
   165				if !app.eventVisibleTo(ev, u) {
   166					continue
   167				}
   168				if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
   169					return
   170				}
   171				cursor = ev.ID
   172			case <-ticker.C:
   173				if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
   174					return
   175				}
   176			}
   177		}
   178	}
   179	
   180	func (app *App) eventVisibleTo(ev RealtimeEvent, u *AuthedUser) bool {
   181		return true
   182	}
   183	
   184	func (app *App) fetchEventsSince(ctx context.Context, u *AuthedUser, since int64, limit int) ([]RealtimeEvent, int64) {
   185		rows, err := app.DB.Pool.Query(ctx, `
   186			SELECT id, type, entity_type, entity_id, payload, created_at, COALESCE(audience_role,''), COALESCE(audience_user_id::text,'')
   187			FROM realtime_events
   188			WHERE id > $1
   189			  AND (audience_role IS NULL OR audience_role = $2)
   190			  AND (audience_user_id IS NULL OR audience_user_id = $3::uuid)
   191			ORDER BY id ASC LIMIT $4`, since, u.ActiveRole, u.UserID, limit)
   192		if err != nil {
   193			return []RealtimeEvent{}, since
   194		}
   195		defer rows.Close()
   196		out := []RealtimeEvent{}
   197		cursor := since
   198		for rows.Next() {
   199			var ev RealtimeEvent
   200			var payloadRaw []byte
   201			var audRole, audUser string
   202			if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityID, &payloadRaw, &ev.CreatedAt, &audRole, &audUser); err != nil {
   203				continue
   204			}
   205			_ = json.Unmarshal(payloadRaw, &ev.Payload)
   206			out = append(out, ev)
   207			if ev.ID > cursor {
   208				cursor = ev.ID
   209			}
   210		}
   211		return out, cursor
   212	}
