    17	// idempotencyLookup returns (status, body, found). If a prior call with the same key
    18	// and endpoint (scoped to the user) exists, its saved response is replayed verbatim.
    19	// If the key was reused with a different request payload, ErrIdempotencyConflict is
    20	// returned via the ok=false, conflict=true signal.
    21	func idempotencyLookup(ctx context.Context, app *App, key, endpoint, userID, reqHash string) (int, map[string]interface{}, bool, bool) {
    22		if key == "" {
    23			return 0, nil, false, false
    24		}
    25		var status int
    26		var bodyRaw []byte
    27		var storedHash string
    28		err := app.DB.Pool.QueryRow(ctx, `
    29			SELECT response_status, response_body, request_hash FROM idempotency_keys
    30			WHERE key=$1 AND endpoint=$2 AND user_id=$3`, key, endpoint, userID).Scan(&status, &bodyRaw, &storedHash)
    31		if err != nil {
    32			return 0, nil, false, false
    33		}
    34		if storedHash != reqHash {
    35			return 0, nil, false, true
    36		}
    37		var body map[string]interface{}
    38		_ = json.Unmarshal(bodyRaw, &body)
    39		return status, body, true, false
    40	}
    41	
    42	func idempotencySave(ctx context.Context, app *App, key, endpoint, userID, reqHash string, status int, body interface{}) {
    43		if key == "" {
    44			return
    45		}
    46		b, _ := json.Marshal(body)
    47		_, _ = app.DB.Pool.Exec(ctx, `
    48			INSERT INTO idempotency_keys (key, endpoint, user_id, request_hash, response_status, response_body)
    49			VALUES ($1,$2,$3,$4,$5,$6)
    50			ON CONFLICT (key, endpoint, user_id) DO NOTHING`,
    51			key, endpoint, userID, reqHash, status, b)
    52	}
    53	
    54	// idempotencyReplay wraps the common "check for a prior identical call" flow used by
    55	// nearly every mutating endpoint. If a prior call is replayed, handled=true and the
    56	// caller must return immediately (the response has already been written). If the key
    57	// was reused with a different payload, handled=true and an idempotency_conflict error
    58	// has already been written. Otherwise handled=false and hash should be passed to
    59	// idempotencySaveResult once the operation succeeds.
    60	func idempotencyReplay(w http.ResponseWriter, ctx context.Context, app *App, endpoint, userID, key string, req interface{}) (hash string, handled bool) {
    61		if key == "" {
    62			writeErr(w, errIdempotencyRequired())
    63			return "", true
    64		}
    65		hash = hashRequest(req)
    66		status, body, found, conflict := idempotencyLookup(ctx, app, key, endpoint, userID, hash)
    67		if conflict {
    68			writeErr(w, errIdempotencyConflict())
    69			return "", true
    70		}
    71		if found {
    72			writeJSON(w, status, body)
    73			return "", true
    74		}
    75		return hash, false
    76	}
    77	
    78	func idempotencySaveResult(ctx context.Context, app *App, endpoint, userID, key, hash string, status int, data interface{}) {
    79		idempotencySave(ctx, app, key, endpoint, userID, hash, status, map[string]interface{}{"data": data})
    80	}
