    25	// haversineKm returns the great-circle distance between two coordinates in kilometers.
    26	func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
    27		const R = 6371.0
    28		dLat := (lat2 - lat1) * math.Pi / 180
    29		dLon := (lon2 - lon1) * math.Pi / 180
    30		a := math.Sin(dLat/2)*math.Sin(dLat/2) +
    31			math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*
    32				math.Sin(dLon/2)*math.Sin(dLon/2)
    33		c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    34		return R * c
    35	}
